using System.Collections;
using System.Collections.Generic;
using Unity.Mathematics;
using UnityEditor.ShaderGraph.Internal;
using UnityEngine;

public class NodeGraph
{
    /// <summary>
    /// The cards in this nodegraph
    /// </summary>
    List<Card> cards = new();

    /// <summary>
    /// A buffer that collects and stores the nodes. The nodegraph should never need to generate its own nodes.
    /// </summary>
    List<Node> nodesBuffer = new();
    /// <summary>
    /// A collection of all the static links generated by the cards. None of these should be generated by nodegraph.
    /// </summary>
    List<NodeLink> cardLinks = new();
    /// <summary>
    /// All the dynamic links between pins generated by the node graph, indexed by a unique ID value generated from a given pair of Card objects.
    /// These links are the ones that can be culled by the compute shader if they intersect with each other, or the cardLinks.
    /// </summary>
    Dictionary<ulong, NodeLink> pinLinks = new();
    /// <summary>
    /// Links generated between nodes on different cards. These are not considered when checking for collisions, as they're just for pathfinding.
    /// However, they will have their collisions checked against just the cardLinks, and will destroy themselves if they collide with any of the card links.
    /// </summary>
    List<NodeLink> intercardLinks = new();
    /// <summary>
    /// Clear the data that the nodegraph itself generated.
    /// </summary>
    public void Clear()
    {
        pinLinks.Clear();
    }
    /// <summary>
    /// Adds a given card object to this node graph
    /// </summary>
    public void AddCard(Card target)
    {
        cards.Add(target);
    }
    public void AddLink(Card from, Card to)
    {
        //Add the links on each of the cards (so they can generate the necessary pin nodes)
        from.AddLink(to);
        to.AddLink(from);

        //Generates the link object representing the link between the two cards.
        pinLinks.Add(Card.GetCardPairID(from, to), new NodeLink(
            from.GetLinkingNode(to), //Get the node on the "from" card that represents the pin that will be connected to "to"
            to.GetLinkingNode(from) //Get the node on the "to" card that represents the pin that will be connected to "from"
            ));
    }
    public void RemoveLink(Card a, Card b)
    {
        a.RemoveLink(b);
        b.RemoveLink(a);

        pinLinks.Remove(Card.GetCardPairID(a, b));
    }
    public void Build()
    {
        //Clear previously buffered data
        nodesBuffer.Clear();
        cardLinks.Clear();
        intercardLinks.Clear();
        foreach (Card card in cards)
        {
            nodesBuffer.AddRange(card.CornerNodes);
            nodesBuffer.AddRange(card.PinNodes);
            cardLinks.AddRange(card.AllNodeLinks);
        }
        GenerateIntercardLinks();
    }
    public void GenerateIntercardLinks()
    {
        for (int a = 0; a < nodesBuffer.Count; a++)
        {
            //Initialising b to a will ensure we're only evaluating pairs that haven't been evaluated yet
            for (int b = a; b < nodesBuffer.Count; b++)
            {
                //If at least one of them are not a pin
                if (!(nodesBuffer[a].isPin && nodesBuffer[b].isPin))
                {
                    //If they originate from different cards
                    if (nodesBuffer[a].owner != nodesBuffer[b].owner)
                    {
                        intercardLinks.Add(new NodeLink(nodesBuffer[a], nodesBuffer[b]));
                    }
                }
            }
        }
    }
    bool[] cullIntercardLinks;
    public void RunComputeShader(ComputeShader shader)
    {
        int offset = cardLinks.Count;
        int total = cardLinks.Count + intercardLinks.Count;
        float4[] linkArray = new float4[total];
        float[] hitsArray = new float[intercardLinks.Count];
        for (int i = 0; i < cardLinks.Count; i++)
        {
            linkArray[i] = (float4)cardLinks[i];
        }
        for (int i = 0; i < intercardLinks.Count; i++)
        {
            linkArray[i + offset] = (float4)intercardLinks[i];
        }

        //Temporarily moving the logic out of the shader to ensure that the actual logic is correct
        for (int id = 0; id < linkArray.Length; id++)
        {
            int intercardIndex = id / offset;
            int cardIndex = id % offset;

            Vector2 A = new Vector2(linkArray[intercardIndex].x, linkArray[intercardIndex].y);
            Vector2 B = new Vector2(linkArray[intercardIndex].z, linkArray[intercardIndex].w);
            Vector2 C = new Vector2(linkArray[cardIndex].x, linkArray[cardIndex].y);
            Vector2 D = new Vector2(linkArray[cardIndex].z, linkArray[cardIndex].w);

            float r = (A.y - C.y) * (D.x - C.x) - (A.x - C.x) * (D.y - C.y) /
                (B.x - A.x) * (D.y - C.y) - (B.y - A.y) * (D.x - C.x);

            float s = (A.y - C.y) * (B.x - A.x) - (A.x - C.x) * (B.y - A.y) /
                (B.x - A.x) * (D.y - C.y) - (B.y - A.y) * (D.x - C.x);

            float hitResult = Mathf.Max(
                (r >= 0 && r <= 1 && s >= 0 && s <= 1) ? 1f : 0f,
                ((A == C) || (A == D) || (B == D)) ? 1f : 0f
                );

            hitsArray[intercardIndex] = Mathf.Max(
                hitsArray[intercardIndex],
                hitResult
                );
        }
        cullIntercardLinks = new bool[intercardLinks.Count];
        for (int i = 0; i < hitsArray.Length; i++)
        {
            cullIntercardLinks[i] = hitsArray[i] > 0 ? true : false;
        }

        //remove
        debugOffsetBuffer = offset;
        debugTotalBuffer = total;
        debugLinkArrayBuffer = linkArray;

        /*ComputeBuffer linkBuffer = new ComputeBuffer(linkArray.Length, sizeof(float) * 4);
        linkBuffer.SetData(linkArray);
        ComputeBuffer hitBuffer = new ComputeBuffer(hitsArray.Length, sizeof(float));
        hitBuffer.SetData(hitsArray);

        shader.SetInt("offset", offset);
        shader.SetInt("total", total);
        shader.SetBuffer(0, "links", linkBuffer);
        shader.SetBuffer(0, "hits", hitBuffer);
        shader.Dispatch(0, Mathf.CeilToInt(linkArray.Length / 64f), 1, 1);

        cullIntercardLinks = new bool[intercardLinks.Count];
        hitBuffer.GetData(hitsArray);
        for (int i = 0; i < hitsArray.Length; i++)
        {
            Debug.Log(hitsArray[i]);
            cullIntercardLinks[i] = hitsArray[i] > 0 ? true : false;
        }
        linkBuffer.Dispose();
        hitBuffer.Dispose();*/
    }
    int debugOffsetBuffer;
    int debugTotalBuffer;
    float4[] debugLinkArrayBuffer;
    public IEnumerator DebugShaderOneAtATime()
    {
        int totalIterations = debugOffsetBuffer * (debugTotalBuffer - debugOffsetBuffer);
        //Temporarily moving the logic out of the shader to ensure that the actual logic is correct
        for (int id = 0; id < totalIterations; id++)
        {
            int intercardIndex = (id / debugOffsetBuffer) + debugOffsetBuffer;
            int cardIndex = id % debugOffsetBuffer;

            Vector2 A = new Vector2(debugLinkArrayBuffer[intercardIndex].x, debugLinkArrayBuffer[intercardIndex].y);
            Vector2 B = new Vector2(debugLinkArrayBuffer[intercardIndex].z, debugLinkArrayBuffer[intercardIndex].w);
            Vector2 C = new Vector2(debugLinkArrayBuffer[cardIndex].x, debugLinkArrayBuffer[cardIndex].y);
            Vector2 D = new Vector2(debugLinkArrayBuffer[cardIndex].z, debugLinkArrayBuffer[cardIndex].w);

            float r = (A.y - C.y) * (D.x - C.x) - (A.x - C.x) * (D.y - C.y) /
                (B.x - A.x) * (D.y - C.y) - (B.y - A.y) * (D.x - C.x);

            float s = (A.y - C.y) * (B.x - A.x) - (A.x - C.x) * (B.y - A.y) /
                (B.x - A.x) * (D.y - C.y) - (B.y - A.y) * (D.x - C.x);

            if ((A == C) || (A == D) || (B == C) || (B == D))
            {
                //The points were touching at the edges, so we should ignore the "collision"
            }

            Debug.Log("r: " + r + ", s: " + s);
            bool hit = (r >= 0 && r <= 1 && s >= 0 && s <= 1);
            Debug.Log(hit ? "hit" : "no");
            Debug.DrawLine(A, B, hit ? Color.white : Color.green, 0.5f);
            Debug.DrawLine(C, D, hit ? Color.white : Color.green, 0.5f);

            yield return new WaitForSeconds(0.5f);
        }
    }
    public void DebugRender()
    {
        foreach (NodeLink cardLink in cardLinks)
        {
            Debug.DrawLine(cardLink.StartPos, cardLink.EndPos, Color.blue);
        }
        foreach (NodeLink pinLink in pinLinks.Values)
        {
            Debug.DrawLine(pinLink.StartPos, pinLink.EndPos, Color.red);
        }
        /*for (int i = 0; i < intercardLinks.Count; i++)
        {
            if (cullIntercardLinks != null)
            {
                if (!cullIntercardLinks[i])
                {
                    Debug.DrawLine(intercardLinks[i].StartPos, intercardLinks[i].EndPos, Color.green);
                }
            }
        }*/
    }
    public Vector3[] DebugNodePositions()
    {
        Vector3[] allPos = new Vector3[nodesBuffer.Count];

        for (int i = 0; i < nodesBuffer.Count; i++)
        {
            allPos[i] = nodesBuffer[i].position;
        }

        return allPos;
    }
}